package com.ptraam.tracker;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.text.*;import java.util.*;import java.util.concurrent.*;
public final class LeaveActivity extends Activity{
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private Spinner type;private Button from,to,submit;private EditText reason;private TextView message,history;private String fromDate="",toDate="";private boolean busy;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(!Session.valid(this)){startActivity(new Intent(this,LoginActivity.class));finish();return;}setContentView(R.layout.activity_leave);type=findViewById(R.id.leave_type);from=findViewById(R.id.leave_from);to=findViewById(R.id.leave_to);submit=findViewById(R.id.leave_submit);reason=findViewById(R.id.leave_reason);message=findViewById(R.id.leave_message);history=findViewById(R.id.leave_history);from.setOnClickListener(v->date(true));to.setOnClickListener(v->date(false));submit.setOnClickListener(v->submit());findViewById(R.id.leave_back).setOnClickListener(v->finish());load();}
 private void date(boolean first){Calendar c=Calendar.getInstance();new DatePickerDialog(this,(v,y,m,d)->{String value=String.format(Locale.ROOT,"%04d-%02d-%02d",y,m+1,d);if(first){fromDate=value;from.setText("From: "+value);}else{toDate=value;to.setText("To: "+value);}},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
 private void load(){call("/workforce/state",new JSONObject(),false);}private void submit(){if(busy)return;if(type.getSelectedItem()==null||fromDate.isEmpty()||toDate.isEmpty()){message.setText("Choose leave type and both dates.");return;}if(toDate.compareTo(fromDate)<0){message.setText("To date cannot be before From date.");return;}try{call("/leave/request",new JSONObject().put("type",type.getSelectedItem().toString()).put("from",fromDate).put("to",toDate).put("reason",reason.getText().toString()),true);}catch(Exception e){message.setText("Check the request.");}}
 private void call(String path,JSONObject body,boolean submitted){busy=true;submit.setEnabled(false);worker.execute(()->{try{JSONObject r=Api.post(this,path,body,true);runOnUiThread(()->{busy=false;submit.setEnabled(true);JSONArray types=r.optJSONArray("leaveTypes");if(types!=null){ArrayList<String> values=new ArrayList<>();for(int i=0;i<types.length();i++)values.add(types.optString(i));type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));}JSONArray rows=r.optJSONArray("leave");StringBuilder text=new StringBuilder();if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject x=rows.optJSONObject(i);text.append(x.optString("from")).append(" to ").append(x.optString("to")).append(" · ").append(x.optString("type")).append(" · ").append(x.optString("status")).append('\n');}history.setText(text.length()==0?"No leave requests.":text.toString().trim());message.setText(submitted?"Leave request submitted.":"");});}catch(Exception e){runOnUiThread(()->{busy=false;submit.setEnabled(true);message.setText(e.getMessage());});}});}@Override public void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
